func compareSignals(vs []VersionItem) string {
	from, to := "1", "1"
	if len(vs) > 0 {
		to = itoa(vs[0].Number)
	}
	if len(vs) > 1 {
		from = itoa(vs[1].Number)
	}
	return "{_wk: {cmp: {from: '" + from + "', to: '" + to + "'}}}"
}

func versionMessage(v VersionItem) string {
	if v.Message != "" {
		return v.Message
	}
	switch v.Reason {
	case "created":
		return "Created"
	case "seed":
		return ""
	}
	return ""
}

